  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title explicitly identifies the report as a systematic review (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Post-ERCP adverse events in children: a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title conveys the population (children) and the focus/exposure (post-ERCP adverse events, specifically post-ERCP pancreatitis incidence)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "a systematic review and meta-analysis of postERCP pancreatitis incidence with synthesis of risk factors and prevention strategies",
      "reason": "The title provides supplementary information on analysis methods (meta-analysis) and scope (synthesis of risk factors and prevention strategies)."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Endoscopic retrograde cholangiopancreatography (ERCP) is increasingly used in children with pancreatobiliary disease, but pediatric adverse-event estimates remain variable.",
      "reason": "The abstract background briefly states the current state of knowledge (increasing pediatric ERCP use) and an uncertainty (variable adverse-event estimates), but the retrieved evidence does not include a full Introduction section elaborating existing knowledge and uncertainties in detail."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "We updated the evidence on post-ERCP adverse events in children, pooled post-ERCP pancreatitis (PEP) incidence when study-level data allowed, and summarized reported risk factors and prevention strategies.",
      "reason": "The need for the review is implied by the stated aim to update evidence and provide a current benchmark ('The pooled estimate provides a current benchmark'), but the importance and need for conducting the review are not explicitly argued in a dedicated rationale statement in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "We updated the evidence on post-ERCP adverse events in children... Prior systematic reviews and meta-analyses were used for background comparison and reference checking only.",
      "reason": "The manuscript indicates it is an update and that prior systematic reviews exist and were used for benchmarking, but the retrieved evidence does not identify or cite a specific previous systematic review to justify the need for the current update."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of adverse-event incidence (prognostic/descriptive), not a review of intervention effects; no intervention whose mechanism of action needs describing is evaluated."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of complex interventions; no logic model is required, and none is reported in the retrieved evidence."
    }
  ],
  "confidence": 72
}

