  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Inclusion Criteria: Study Type: Original pediatric studies, including cohort studies, case-control studies, and randomized or nonrandomized interventional studies... Population: Pediatric patients (<18 years) undergoing ERCP. Outcomes: Reported incidence, types, risk factors, or management strategies of post-ERCP complications.",
      "reason": "Eligible study designs, population, and outcome requirements are explicitly specified in the inclusion/exclusion criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Language: English. Publication Date: January 1, 2015 to June 26, 2025.",
      "reason": "Language and dissemination date range are specified, but no publication or report status restriction (e.g., peer-reviewed vs grey literature) is stated."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": "Data Availability: Incomplete or unextractable data.",
      "reason": "Exclusion for data availability is mentioned, but the review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We prespecified subgroup exploration by age group, ERCP indication, procedure type, pancreatic duct manipulation or contrast injection, sphincterotomy, and operator or center volume.",
      "reason": "Synthesis groups (subgroups, denominator-unit categories, PEP vs other outcomes) are described, but they are not explicitly linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The search was limited to studies published between January 1, 2015, and June 26, 2025, to capture contemporary pediatric ERCP practice, including changes in therapeutic indications, endoscopic accessories, anesthesia support, and prophylaxis strategies.",
      "reason": "A rationale is provided for the notable date restriction on eligibility."
    }
  ],
  "confidence": 88
}

