{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "we collected first author, year, country, study design, sample size, number of ERCP procedures, mean or median age, ERCP indications, procedure type, follow-up duration, adverse-event definitions or reporting windows, event numerators and denominators for PEP, bleeding, perforation, cholangitis or infection, severity classification, risk factors, and management strategies",
      "reason": "Outcomes (PEP, bleeding, perforation, cholangitis/infection, severity, risk factors, management) are listed and extraction of adverse-event definitions/reporting windows is described, but formal definitions of each outcome domain are not fully provided."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "adverse-event definitions or reporting windows",
      "reason": "The extraction form captured 'reporting windows' and 'follow-up duration' as reported by sources, but no prespecified time frame of measurement for each outcome domain is specified by the reviewers themselves."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Meta-analysis was conducted only for outcomes reported by at least three non-overlapping primary studies with extractable numerators and denominators.",
      "reason": "The manuscript implies selection of extractable results (e.g., only studies with extractable numerators/denominators pooled; risk factors summarized narratively when not poolable), but it does not explicitly state whether all compatible results within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Formal subgroup meta-analysis was not forced when studies did not provide stratified PEP event counts... These variables were therefore summarized as explanatory domains for heterogeneity and risk.",
      "reason": "Some selection processes are described (pooling only outcomes with ≥3 studies with extractable data; narrative synthesis otherwise), but a general method for deciding which results to collect within each outcome domain is not fully articulated."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "In response to peer review, we also added a post hoc denominator-unit sensitivity summary, separating procedure-level studies from patient-level or first-ERCP-perchild studies",
      "reason": "A post hoc analysis change is reported with rationale (peer review), but this concerns analysis strategy rather than outcome-domain inclusion or definitions; no changes to outcome definitions are reported."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within eligible outcome domains are reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Random-effects pooling was performed for PEP because this outcome had the most consistently extractable numerators and denominators. Bleeding, perforation, and cholangitis were less frequent and were summarized descriptively",
      "reason": "PEP is identified as the primary/most important outcome with rationale (most consistently extractable data; most frequent and clinically significant complication), while other outcomes were summarized descriptively."
    }
  ],
  "confidence": 78
}

